# Generated by Descant: acceptance tests.

require "rails_helper"
require "puma"
require "puma/server"
require_relative "../../../spec/support/timekeeping/fake_relay"

# Runs the queue processes config/solid_queue.yml names in a child process, so
# delivery is seen only if the dispatcher schedules RelayJob and the worker runs it.
RSpec.describe RelayJob, "through the configured queue worker when paused, resumed and run again", type: :request do
  self.use_transactional_tests = false

  after do
    ApplicationRecord.connection.execute(<<~SQL.squish)
      TRUNCATE outbox_snapshots, solid_queue_blocked_executions, solid_queue_claimed_executions,
        solid_queue_failed_executions, solid_queue_pauses, solid_queue_processes, solid_queue_ready_executions,
        solid_queue_recurring_executions, solid_queue_recurring_tasks, solid_queue_scheduled_executions,
        solid_queue_semaphores, solid_queue_jobs CASCADE
    SQL
  end

  it "a worker run while paused sends nothing, and after resume the row reaches the projection exactly once across later ticks" do
    app_root = File.expand_path("../..", __dir__)
    fake_timekeeping = TimekeepingContract::FakeTimekeeping.new
    token = fake_timekeeping.add_service(company_id: nil, name: "timekeeping", operations: ["deliver"])
    projection = TimekeepingContract::FakeRelay.new(source: fake_timekeeping)
    posted_positions = []
    posted_lock = Mutex.new

    listener_app = lambda do |env|
      body = JSON.parse(env["rack.input"].read)
      posted_lock.synchronize do
        posted_positions.concat(body.fetch("snapshots").map { |item| item.fetch("outbox_position") })
      end
      answer = projection.call("POST", env["PATH_INFO"],
                               headers: { "Authorization" => env["HTTP_AUTHORIZATION"],
                                          "Idempotency-Key" => env["HTTP_IDEMPOTENCY_KEY"] },
                               body:)
      [answer.status, { "content-type" => "application/json" }, [JSON.generate(answer.body)]]
    end
    listener = Puma::Server.new(listener_app, nil, min_threads: 1, max_threads: 2)
    listener.add_tcp_listener("127.0.0.1", 0)
    listener_url = "http://127.0.0.1:#{listener.connected_ports.first}"
    listener.run

    log = Tempfile.new("relay_worker")
    child_env = ENV.to_h.slice(*%w[PATH HOME GEM_HOME GEM_PATH BUNDLE_PATH BUNDLE_APP_CONFIG]).merge(
      "RAILS_ENV" => "test",
      Timekeeping::Environment::DATABASE_URL => Timekeeping::Environment.database_url,
      Timekeeping::Environment::MONOLITH_SNAPSHOT_URL => listener_url,
      Timekeeping::Environment::SERVICE_TOKEN => token
    )
    supervisor_script = "WebMock.disable_net_connect!(allow_localhost: true); SolidQueue::Supervisor.start"
    worker_output = -> { File.read(log.path) }
    wait_for = lambda do |what, seconds, &check|
      deadline = Process.clock_gettime(Process::CLOCK_MONOTONIC) + seconds
      until check.call
        if Process.clock_gettime(Process::CLOCK_MONOTONIC) > deadline
          raise "#{what} not seen within #{seconds}s. Worker output:\n#{worker_output.call}"
        end

        sleep 0.25
      end
    end
    finished_relay_runs_since = lambda do |time|
      SolidQueue::Job.where(class_name: "RelayJob").where(created_at: time..).where.not(finished_at: nil).count
    end
    hook_headers = { "Authorization" => "Bearer #{token}" }

    pid = Process.spawn(child_env, RbConfig.ruby, "bin/rails", "runner", supervisor_script,
                        chdir: app_root, unsetenv_others: true, pgroup: true, out: log.path, err: log.path)
    begin
      with_timekeeping_env(Timekeeping::Environment::SERVICE_TOKEN => token) do
        wait_for.call("Solid Queue worker and dispatcher registration", 30) do
          SolidQueue::Process.where(kind: %w[Worker Dispatcher]).count >= 2
        end

        post "/internal/v1/test-hooks/relay/pause", headers: hook_headers
        expect(response).to have_http_status(:success)

        stamp = Time.utc(2026, 3, 2, 9)
        inserted_at = Time.current
        OutboxSnapshot.insert_all!([{
          outbox_position: 9601, id: 9601, project_id: 3, user_id: 4, work_date: "2026-03-02", duration: 60.0,
          bill_status: "unbilled", review_status: "not_required", locked: false, source: "manual",
          source_metadata: {}, proof_metadata: {}, created_at: stamp, updated_at: stamp,
          company_id: 1, version: 1, generation: TimekeepingContract::FakeTimekeeping::INITIAL_GENERATION
        }])

        # "Include pause and resume across the request and worker processes so the same check covers the
        # required process boundary." The worker must be seen to run while paused, so a worker that ignores
        # the pause file set by this request process fails here rather than passing on an idle wait.
        wait_for.call("a finished RelayJob run after the paused insert", 25) do
          finished_relay_runs_since.call(inserted_at).positive?
        end
        expect(posted_lock.synchronize { posted_positions.dup }).to be_empty
        expect(OutboxSnapshot.find_by!(outbox_position: 9601).sent_at).to be_nil
        expect(projection.projected_entry(9601)).to be_nil

        post "/internal/v1/test-hooks/relay/resume", headers: hook_headers
        expect(response).to have_http_status(:success)

        wait_for.call("sent_at on the resumed row", 25) do
          OutboxSnapshot.find_by!(outbox_position: 9601).sent_at.present?
        end
        delivered_at = Time.current
        # A later scheduled run must not send the already-sent row again.
        wait_for.call("a finished RelayJob run after delivery", 25) do
          finished_relay_runs_since.call(delivered_at).positive?
        end
      end

      expect(posted_lock.synchronize { posted_positions.dup }).to eq([9601])
      expect(projection.projected_entry(9601)).to include("id" => 9601, "version" => 1, "company_id" => 1)
    ensure
      Timekeeping::TestHooks.resume_relay!
      begin
        Process.kill("TERM", -pid)
      rescue Errno::ESRCH
        nil
      end
      stop_deadline = Process.clock_gettime(Process::CLOCK_MONOTONIC) + 10
      while Process.waitpid(pid, Process::WNOHANG).nil?
        if Process.clock_gettime(Process::CLOCK_MONOTONIC) > stop_deadline
          Process.kill("KILL", -pid)
          Process.waitpid(pid)
          break
        end
        sleep 0.1
      end
      listener.stop(true)
      log.close!
    end

    expect(File.exist?(Timekeeping::TestHooks.relay_pause_file)).to be(false)
  end
end
